/* DKA patient 6 (Samuel Okafor): orders, MAR, devices, stickies. See ../DESIGN.md.
   Doses after Mon 0700 are 'due' (the students give them); only ED doses and infusions started in the ED are charted 'given' (plus the ticagrelor load given in the cath lab).
   Hold / restart / rate changes of the insulin infusion are made and charted by the students per the protocol orders.
   Source order text was cleaned: no web links, program or brand names, no out-of-universe wording; potassium, heparin and ticagrelor timing corrected (see DESIGN.md). */
const { H, at, hOfStamp, hhmm, slug, HOURS } = require('./lib');
const WHO = { ed: 'G. Marsh, MD', hospD: 'F. Pelletier, MD', hospN: 'E. Bouchard, MD', endo: 'I. Ashcroft, MD', cards: 'L. Vitale, MD', fellow: 'A. Vogt, MD', ic: 'R. Quintero, MD', pharm: 'T. Ng, PharmD' };
const RN = { ed: 'O. Linton, RN', cath: 'Cath lab nursing (R. Quintero, MD team)' };
const epic = t => `${t.slice(5, 7)}/${t.slice(8, 10)}/${t.slice(2, 4)} ${t.slice(11, 13)}${t.slice(14, 16)}`;
const N = HOURS + 1;                     // MAR columns Mon 11/16 0700 .. Thu 11/19 0700 (73)
const slot = h => (h < 0 ? -1 : Math.min(N - 1, Math.floor(h + 1e-6)));
const T = (d, t) => at(d, t);
const I = require('./infusions');
const FL = I.FLUSH.map(m => H(m / 60));   // stamps of every 10 mL saline flush (gen/infusions.js)
const orders = [], admins = []; let seq = 0;
const oid = (k, n) => `order_${k}_${slug(n).slice(0, 40)}_${seq++}`;
const ago = (t, m = 6) => H(hOfStamp(t) - m / 60);
const mon = (l, t, c) => ({ label: l, sourceType: t, code: c });
const POC = mon('Glucose (point of care)', 'lab', 'Glucose (point of care)'), KMON = mon('Potassium', 'lab', 'Potassium'), TMON = mon('hs-Troponin I', 'lab', 'hs-Troponin I'), XMON = mon('Heparin anti-Xa', 'lab', 'Heparin anti-Xa'), CRMON = mon('Creatinine', 'lab', 'Creatinine');

function plain(category, name, start, o = {}) {
  const id = oid(slug(category).slice(0, 6), name);
  // an order placed earlier than its start shows as "Pending" until the start time (app.js getVisibleCanonicalCase)
  orders.push(Object.assign({ id, name, category, status: 'Active', frequency: 'Continuous', start, end: '', orderedAt: ago(start, 6), provider: WHO.hospD, instructions: '', rationale: '', linkedData: [], nursingConsiderations: [] }, o)); return id;
}
function med(c) {
  const id = oid('med', c.key || c.name), startH = hOfStamp(c.start), endStamp = c.end || '', dose = c.dose, route = c.route;
  const o = {
    id, name: c.name, category: 'Medication', status: c.status || 'Active', frequency: c.frequency, start: c.start, end: endStamp, orderedAt: c.orderedAt || ago(c.start, 6), provider: c.provider || WHO.hospD,
    instructions: c.instructions || `Administer ${dose} ${route} ${c.frequency}.`, rationale: c.rationale || '', linkedData: [], nursingConsiderations: c.nursing || [],
    medication: { medKey: c.key || slug(c.name), drugClass: c.drugClass || '', dose, route, importantInfo: c.info || '', monitoringRules: c.monitor || [], highAlert: !!c.highAlert, freqKey: c.frequency, prn: !!c.prn, at: [], hold: c.hold || '', expires: '', barcode: '', expiredDecoy: false, edited: false, custom: false },
    mar: { category: c.kind === 'cont' ? 'continuous' : c.prn ? 'prn' : 'scheduled', orderStartIndex: Math.max(0, Math.min(N - 1, slot(startH))), adminDose: c.adminDose || dose, dispenseLocation: c.dispense || (/^IV/i.test(route) ? 'Central Pharmacy (IV room)' : 'Pharmacy to load in ADS'), completed: false, lastAdmin: '' }
  };
  if (c.concentration) o.mar.concentration = c.concentration;
  if (endStamp) { o.stoppedEarly = !!c.stoppedEarly; o.mar.discontinuedIndex = Math.max(0, Math.min(N - 1, slot(hOfStamp(endStamp)))); }
  orders.push(o);
  const give = (t, state, label, d, extra) => { const h = hOfStamp(t); admins.push(Object.assign({ id: `admin_${id}_${admins.length}`, orderId: id, slotIndex: slot(h), time: hhmm(h), state, label, dose: d || dose, route }, state === 'given' ? { administeredTime: epic(t), administeredAt: t, administeredBy: c.by || RN.ed, availableAt: t } : {}, extra || {})); };
  (c.times || []).forEach((t, i) => give(t, 'given', `${hhmm(hOfStamp(t))} Given ${(c.doses && c.doses[i]) || dose}`, (c.doses && c.doses[i]) || dose));
  (c.events || []).forEach(([t, label, d]) => give(t, 'given', `${hhmm(hOfStamp(t))} ${label}`, d));
  // an infusion already running at the 0700 handoff shows "Running" in the first MAR column (checked at the ED-to-step-down handoff)
  if (c.running) give(T('Mon', '07:00'), 'given', `0700 Running ${c.running} (started in the ED; checked at handoff)`, c.running, { administeredBy: `${RN.ed} (handoff)` });
  (c.due || []).forEach((t, i) => give(t, 'due', `${hhmm(hOfStamp(t))} Due`, (c.dueDoses && c.dueDoses[i]) || dose));
  if (endStamp && c.kind === 'cont' && c.stoppedEarly) { const h = hOfStamp(endStamp); admins.push({ id: `admin_${id}_stop`, orderId: id, slotIndex: slot(h), time: hhmm(h), state: 'discontinued', label: `${hhmm(h)} Discontinued${c.stopLabel ? ' - ' + c.stopLabel : ''}`, dose, route, availableAt: endStamp }); }
  return id;
}

const KRULE = 'PERIPHERAL POTASSIUM SAFETY PROTOCOL (two peripheral IVs, no central line; acute coronary syndrome, so the goal is K 4.0-5.0): before ANY potassium, confirm urine output of at least 0.5 mL/kg/h (40 mL/h at 80 kg) and review the latest creatinine. TOTAL IV potassium from ALL sources on ALL lines must NEVER exceed 10 mEq per hour. While a KCl rider runs the carrier fluid must be POTASSIUM-FREE: swap the 20 mEq/L bag for the plain carrier BEFORE the rider starts (the 20 mEq/L carrier gives 3 mEq/h at 150 mL/h) and put the 20 mEq/L carrier back only after the last rider. Riders are premixed KCl 10 mEq in 100 mL over 1 hour on a pump, ONE at a time, never in parallel, never IV push; no 40 mEq/L bags (central-line strength). K above 5.0 = no potassium, recheck in 2-4 hours. K 4.0-5.0 = carrier with KCl 20 mEq/L. K 3.5-3.9 = two sequential riders (20 mEq) with the potassium-free carrier, then the 20 mEq/L carrier again; recheck after the second. K UNDER 3.5 = HOLD the insulin infusion and notify the prescriber at once; four sequential riders (40 mEq over 4 hours) with the potassium-free carrier; recheck K when the fourth rider ends, drawn from the arm opposite the infusion; restart insulin only when K is 3.5 or higher AND the prescriber confirms (goal 4.0 or higher). Stop replacement and call urgently for an unexpected result, urine under 40 mL/h, a new arrhythmia, extravasation or new pain at the site. Inspect the site and ask about pain every hour during a rider; do not speed the rate. Continuous telemetry throughout.';
const IRULE = 'Insulin titration (POC glucose every hour): glucose under 250 with K 3.5 or higher = add 5% dextrose to the carrier and run 0.05 unit/kg/h (4 units/h); then change the rate by 0.5-1 unit/h to keep the glucose 150-200 until DKA resolves. Falling more than 100 mg/dL in an hour or glucose under 150: call the prescriber for a rate review (reduce, do not stop, while ketones persist). Glucose under 100: call at once and recheck in 15 minutes; glucose under 70: hold the insulin, treat with the hypoglycemia order and check every 15 minutes. DKA is resolved ONLY when beta-hydroxybutyrate is under 0.6 AND (venous pH 7.30 or higher OR bicarbonate 18 or higher); a closed anion gap or a normal glucose alone is not enough.';

// ---------------- ED treatment (charted as given). Weight 80.0 kg (ED measured) is the dosing weight for the whole stay.
plain('Code Status', 'Full Code (wife Grace Okafor is the emergency contact)', T('Mon', '01:30'), { provider: WHO.ed, orderedAt: T('Mon', '01:30') });
plain('Nursing', 'Establish two peripheral IVs in the ED (18 gauge, left forearm and right antecubital; no central line). Assess every site hourly during infusions; remove when no longer needed', T('Mon', '01:30'), { provider: WHO.ed, orderedAt: T('Mon', '01:30'), end: T('Thu', '07:00'), instructions: 'Heparin runs alone on the right antecubital IV; the left forearm IV carries the carrier fluid, the insulin and, later, the potassium riders, each on its own pump channel. After the right radial catheterization no blood pressure cuff, venipuncture or IV on the right arm. Priming volume is discarded and not counted as intake.' });
plain('Nursing', 'Continuous 5-lead ST-segment telemetry (V5 and lead II) through discharge; vital signs every hour while on the insulin infusion, then every 4 hours; strict intake and output with every void measured (urinal, no catheter); hourly urine while on the insulin infusion', T('Mon', '01:35'), { provider: WHO.ed, orderedAt: T('Mon', '01:35'), end: T('Thu', '07:00'), instructions: 'Notify for chest or epigastric pain, new ST change or ectopy, urine under 40 mL/h for 2 hours, new crackles or oxygen need, glucose under 150 on the infusion, or any infusion-site injury.' });
plain('Cardiology', 'ECG 12-lead now (epigastric ache with diaphoresis and nausea in a man with type 1 diabetes); acquire 0140, interpretation released 0150', T('Mon', '01:40'), { provider: WHO.ed, orderedAt: T('Mon', '01:35'), frequency: 'Once', end: T('Mon', '01:50') });
plain('Lab / Bedside Testing', 'Initial labs (ED) at 0140: venous blood gas, BMP, magnesium, phosphorus, beta-hydroxybutyrate, hs-troponin I, hepatic panel, lipid panel, CBC, HbA1c; urinalysis. Repeat chemistry, venous gas, BHB, magnesium, phosphorus and hs-troponin I at 0430 and again with the 0700 panel (troponin not repeated at 0700). POC glucose hourly from the insulin start', T('Mon', '01:40'), { provider: WHO.ed, orderedAt: T('Mon', '01:35'), end: T('Mon', '07:00'), frequency: 'As listed', instructions: 'Results are released 20-30 minutes after collection. Draw from an arm without an infusion running.' });
med({ key: 'ns_bolus_ed', name: '0.9% sodium chloride 1,000 mL bolus (ED)', dose: '1,000 mL over 1 hour', route: 'IV', frequency: 'Once, reassess lungs and perfusion at the end; no automatic repeat bolus', kind: 'sched', start: T('Mon', '01:45'), end: T('Mon', '02:45'), provider: WHO.ed, orderedAt: T('Mon', '01:40'), drugClass: 'Isotonic crystalloid', rationale: 'Dry mucous membranes, tachycardia and a 3.5 L estimated deficit (usual weight 83.5 kg versus 80.0 kg). One liter in the first hour (not 1-1.5 L/h repeated) because an acute coronary syndrome is likely: avoid volume overload on an ischemic ventricle.', instructions: 'Reassess breath sounds and work of breathing at the end of the hour.', times: [T('Mon', '01:45')], doses: ['1,000 mL over 1 hour (0145-0245)'], status: 'Completed' });
med({ key: 'aspirin_chew', name: 'aspirin chewable tablets (ED loading dose)', dose: '324 mg (4 x 81 mg)', route: 'Oral', frequency: 'Once, chewed', kind: 'sched', start: T('Mon', '01:45'), end: T('Mon', '01:50'), provider: WHO.ed, orderedAt: T('Mon', '01:40'), drugClass: 'Antiplatelet', rationale: 'ST depression V4-V6 on the 0140 ECG with a suspected acute coronary syndrome and no aspirin allergy.', times: [T('Mon', '01:45')], doses: ['324 mg chewed (0145)'], status: 'Completed' });
med({ key: 'ondansetron', name: 'ondansetron (ZOFRAN) injection, as needed', dose: '4 mg', route: 'IV', frequency: 'Every 6 hours as needed for nausea or vomiting, slowly over 2 minutes; check potassium, magnesium and the ECG QTc before any repeat dose', kind: 'prn', prn: true, start: T('Mon', '01:45'), end: T('Wed', '19:00'), provider: WHO.ed, orderedAt: T('Mon', '01:40'), drugClass: 'Antiemetic', rationale: 'Nausea and vomiting. QT-prolonging: avoid repeating while potassium is low or the QTc is long (the ECG at 0715 had a long QTc with U waves).', events: [[T('Mon', '01:45'), 'Given 4 mg IV push', '4 mg']] });
const insulinDrip = med({ key: 'insulin_regular_infusion', name: 'insulin regular (HUMULIN R) 100 units in 0.9% sodium chloride 100 mL (1 unit/mL) infusion - DKA', dose: '0.1 unit/kg/h = 8 units/h (8 mL/h), no bolus', route: 'IV', frequency: 'Continuous (adult DKA protocol); HOLD for K under 3.5', kind: 'cont', start: T('Mon', '02:15'), end: T('Mon', '21:30'), stoppedEarly: true, stopLabel: 'transition complete (2-hour overlap with glargine)', provider: WHO.ed, orderedAt: T('Mon', '02:10'), drugClass: 'Short-acting insulin (IV)', highAlert: true, concentration: '1 unit/mL', dispense: 'Central Pharmacy (IV room); premixed DKA insulin bag',
  rationale: '80 kg x 0.1 unit/kg/h = 8 units/h; no bolus. Started at 0215 after the first potassium (5.2, above 3.5) was known. When the glucose falls under 250 dextrose is added and the rate drops to 0.05 unit/kg/h = 4 units/h. The infusion is held for any K under 3.5 (insulin drives potassium into cells, and ventricular ectopy in an ischemic heart can become ventricular tachycardia).',
  instructions: 'Regular insulin 100 units in NS to 100 mL (1 unit/mL) on its own pump channel, 8 units/h, NO bolus. Independent two-nurse check of drug, concentration and rate at initiation and every change. POC glucose hourly, including any hold. HOLD at once for K under 3.5, glucose under 70 or urgent deterioration and notify. Restart only when K is 3.5 or higher AND the prescriber confirms. ' + IRULE + ' Final stop only with the transition order and the glargine overlap.',
  info: 'Insulin moves potassium into cells: the blood level can fall quickly (5.2 to 4.3 in 2 hours here). Ketones and acid-base decide when insulin stops, not the glucose number.',
  nursing: ['Hourly POC glucose; strict I&O; telemetry.', 'High-alert drug: two-nurse check of drug, concentration, rate and patient.', 'Stop only by order, after the first subcutaneous basal insulin dose has had its overlap.'],
  events: [[T('Mon', '02:15'), 'Started 8 units/h (0.1 unit/kg/h), no bolus', '8 units/h']], running: '8 units/h',
  due: [T('Mon', '07:15'), T('Mon', '11:30'), T('Mon', '19:15')], dueDoses: ['Potassium check: HOLD the infusion if the potassium is under 3.5 (see the 0655 panel and the protocol order); notify the prescriber', 'Restart at 4 units/h (0.05 unit/kg/h) only when the repeat potassium is 3.5 or higher AND the prescriber confirms', 'Per the transition order: reduce to 2 units/h once DKA is resolved (BHB under 0.6 plus venous pH 7.30 or higher or bicarbonate 18 or higher); glargine due at 1930'], monitor: [POC, KMON, mon('pH, blood gas', 'lab', 'pH, blood gas'), mon('Anion gap', 'lab', 'Anion gap'), mon('Beta-hydroxybutyrate (serum ketone)', 'lab', 'Beta-hydroxybutyrate (serum ketone)')] });
plain('Nursing', 'POTASSIUM SAFETY PROTOCOL: two peripheral IVs; never more than 10 mEq/h from ALL sources; one KCl 10 mEq/100 mL rider at a time with a potassium-free carrier; no 40 mEq/L bags; carrier with KCl 20 mEq/L only when no rider is running; HOLD insulin if K is under 3.5; goal K 4.0-5.0 (acute coronary syndrome); continuous telemetry', T('Mon', '02:10'), { provider: WHO.ed, orderedAt: T('Mon', '02:10'), end: T('Tue', '07:00'), instructions: KRULE, rationale: 'Adult DKA protocol: K under 3.5 is replaced before and during insulin; peripheral lines limit the rate to 10 mEq/h.' });
