med({ key: 'd5_045_nok', name: 'dextrose 5% in 0.45% sodium chloride (no potassium), 1,000 mL bag, carrier during the potassium riders', dose: '50 mL/h', route: 'IV', frequency: 'Continuous 0715-1130 during four riders', kind: 'cont', start: T('Mon', '07:15'), end: T('Mon', '11:30'), stoppedEarly: true, stopLabel: 'riders finished, K 4.1: carrier with KCl 20 mEq/L resumes', provider: WHO.hospD, orderedAt: T('Mon', '07:12'), drugClass: 'Dextrose-containing fluid', concentration: 'D5 0.45% NaCl 1,000 mL bag', dispense: 'Central Pharmacy (IV room)',
  rationale: 'Glucose 235 (under 250) so dextrose is added, but this bag carries NO potassium: the riders supply the potassium (10 mEq/h), so no minute exceeds the peripheral limit. 50 mL/h plus 100 mL/h of rider volume = 150 mL/h total, the rate cardiology set as the ceiling for an ischemic ventricle. Insulin is held, so the 2.5 g/h of dextrose is small.', instructions: '50 mL/h by pump through IV A. Swap the potassium-containing bag out BEFORE the first rider starts. Stays potassium-free until the recheck potassium is back (1130).', due: [T('Mon', '07:15')], dueDoses: ['Start 50 mL/h; stop the 0.45% NaCl + KCl 20 mEq/L bag first'], monitor: [POC] });
plain('Nursing', 'Continuous telemetry with ST-segment monitoring. NOTIFY for chest or epigastric pain, new ST depression, ventricular ectopy (more than 6 per minute, couplets or runs), urine under 40 mL/h for 2 hours, new crackles or oxygen need, bleeding, or any infusion-site injury. Total fluid ceiling today: 150 mL/h of IV fluid including piggybacks unless cardiology changes it. Strict I&O and daily weight', T('Mon', '07:15'), { provider: WHO.hospD, orderedAt: T('Mon', '07:12'), end: T('Tue', '07:00'), instructions: 'Peaked T = high K; flat T with U waves = low K, but a normal tracing does not exclude a dangerous level.' });
plain('Cardiology', 'ECG 12-lead now for frequent PVCs with flat T waves and U waves (K 3.3); acquire 0715, interpretation released 0725', T('Mon', '07:15'), { provider: WHO.hospD, orderedAt: T('Mon', '07:12'), frequency: 'Once', end: T('Mon', '07:25') });
plain('Nursing', 'Activity: bedrest with bedside commode on Day 1 (ST depression, heparin infusion, potassium of 3.3); advance to chair and walking in the room on the morning of Day 2 before the catheterization', T('Mon', '07:15'), { provider: WHO.hospD, orderedAt: T('Mon', '07:12'), end: T('Tue', '10:40'), instructions: 'Stop and call for chest pressure, dizziness or palpitations with any activity.' });
plain('Diet', 'Sugar-free clear liquids as tolerated (nausea has resolved); no solid food until the DKA resolves. Count every oral volume on the I&O', T('Mon', '07:15'), { provider: WHO.hospD, orderedAt: T('Mon', '07:12'), end: T('Mon', '19:30'), stoppedEarly: true });
plain('Consults', 'Cardiology: invasive strategy booked for the morning of Day 2 (coronary angiography with possible PCI, right radial approach, 1100). Endocrinology: follows through discharge. Later orders add the dietitian, cardiac rehabilitation, case management and social work, and the tobacco treatment specialist', T('Mon', '09:35'), { provider: WHO.cards, frequency: 'Once', orderedAt: T('Mon', '09:35'), end: T('Thu', '07:00') });
plain('Lab / Bedside Testing', 'Chemistry, venous gas, BHB, magnesium, phosphorus at 1115 (with hs-troponin I and anti-Xa; draw from the arm opposite the infusion), 1530 and 1850 on Day 1; BMP, magnesium, phosphorus, hs-troponin I and anti-Xa at 0700 on Day 2 (CBC with platelets); BMP and hs-troponin I at 1845 on Day 2; BMP, hs-troponin I, phosphorus and magnesium at 0645 on Day 3 and Day 4 (CBC each morning). POC glucose hourly on the infusion, then before meals, at bedtime and at 0300 once on subcutaneous insulin', T('Mon', '07:15'), { provider: WHO.hospD, orderedAt: T('Mon', '07:12'), end: T('Thu', '07:00'), frequency: 'As listed', instructions: 'Draw from an arm without an infusion; potassium samples from the arm opposite the potassium. More frequent potassium checks for any arrhythmia or deterioration.' });
// ---- 1130: restart
plain('Nursing', 'K 4.1 (1115 specimen, released 1130): the prescriber has reviewed it. RESTART the regular insulin infusion at 4 units/h (0.05 unit/kg/h) at 1130 and change the carrier to D5 0.45% NaCl + KCl 20 mEq/L at 150 mL/h (no rider is running now). Independent two-nurse check of the insulin rate. Continue hourly POC glucose; titrate the insulin by 0.5-1 unit/h to a glucose of 150-200 until DKA resolves (BHB under 0.6 AND venous pH 7.30 or higher or bicarbonate 18 or higher)', T('Mon', '11:30'), { provider: WHO.hospD, orderedAt: T('Mon', '11:30'), end: T('Mon', '19:15'), stoppedEarly: true, instructions: 'Restart needs K 3.5 or higher AND prescriber confirmation (both met). No potassium rider while the 20 mEq/L carrier runs; goal K 4.0-5.0. Ketones are still present (BHB 1.9): do not stop the insulin for a normal glucose.' });
med({ key: 'd5_045_k20', name: 'dextrose 5% in 0.45% sodium chloride + potassium chloride 20 mEq/L, 1,000 mL bag, maintenance', dose: '150 mL/h (3 mEq/h potassium)', route: 'IV', frequency: 'Continuous 1130-2130 with the insulin infusion (peripheral limit 20 mEq/L; never alongside a KCl rider)', kind: 'cont', start: T('Mon', '11:30'), end: T('Mon', '21:30'), stoppedEarly: true, stopLabel: 'stopped with the insulin infusion after the glargine overlap', provider: WHO.hospD, orderedAt: T('Mon', '11:30'), drugClass: 'Dextrose-containing fluid with electrolyte', concentration: 'D5 0.45% NaCl 1,000 mL + KCl 20 mEq', dispense: 'Central Pharmacy (IV room)',
  rationale: 'Dextrose keeps the glucose from falling too fast while insulin clears the ketones; 20 mEq/L keeps K at 4.0 or higher on insulin (3 mEq/h). 150 mL/h (1.9 mL/kg/h) is the ceiling cardiology set for an ischemic ventricle (lungs, urine and weight watched).', instructions: '150 mL/h by pump through IV A. If another potassium rider is ever ordered, swap to the potassium-free carrier first. Check lungs and urine every 2 hours.', due: [T('Mon', '11:30')], dueDoses: ['Start 150 mL/h with the insulin restart once no rider is running and the recheck potassium is back'], monitor: [POC, KMON] });
med({ key: 'ntg_sl', name: 'nitroglycerin (NITROSTAT) sublingual tablet, as needed', dose: '0.4 mg', route: 'Sublingual', frequency: 'Every 5 minutes as needed for chest pressure or ischemic epigastric discomfort; maximum 3 doses in 15 minutes', kind: 'prn', prn: true, start: T('Mon', '11:30'), end: T('Thu', '07:00'), provider: WHO.cards, orderedAt: T('Mon', '09:35'), drugClass: 'Nitrate (vasodilator)', rationale: 'NSTEMI with a risk of recurrent ischemia before catheterization.', instructions: 'Give ONLY if systolic BP is 100 or higher (HOLD and call for systolic BP under 100 or heart rate under 50) and he has taken no phosphodiesterase-5 inhibitor (sildenafil or tadalafil) in the last 48 hours: ask every time. Sit or lie down first. With the FIRST episode: STAT 12-lead ECG within 10 minutes and notify the provider (cardiology fellow). If the discomfort is not relieved 5 minutes after the first dose, call the rapid response team. Document pain score before and after and recheck blood pressure before each dose.', hold: 'Systolic BP under 100, heart rate under 50, or a phosphodiesterase-5 inhibitor within 48 hours' });
plain('Cardiology', 'ECG 12-lead STAT for chest pressure (new, 5/10); acquire 1405, interpretation released 1415', T('Mon', '14:05'), { provider: WHO.fellow, orderedAt: T('Mon', '14:05'), frequency: 'Once', end: T('Mon', '14:15') });
// ---- transition (written 1915-1945 after the 1905 resolution labs)
med({ key: 'glargine_22', name: 'insulin glargine (LANTUS) pen U-100 (first inpatient basal dose, then bedtime)', dose: '22 units', route: 'Subcutaneous', frequency: 'First dose at 1930 on Day 1 (2 hours before the infusion stops); then every 24 hours at 2100 from Day 2', kind: 'sched', start: T('Mon', '19:30'), end: T('Thu', '07:00'), provider: WHO.endo, orderedAt: T('Mon', '19:15'), drugClass: 'Long-acting (basal) insulin', highAlert: true, dispense: 'Pharmacy: patient-specific pen',
  rationale: 'DKA resolved on the 1850 specimen (BHB 0.4, venous pH 7.38, bicarbonate 19 or higher at 22, gap 12). Basal insulin goes in 2 hours BEFORE the infusion stops. 22 units = 0.275 unit/kg (home dose 24 units; slightly lower after the missed doses and with new beta-blocker therapy that can hide a low). Basal insulin is never omitted in type 1 diabetes, even when NPO.', instructions: 'Give at 1930 with the IV insulin and the carrier still running; both stop at 2130 only after the dose is verified and he is eating. The next dose is at 2100 on Day 2 (25.5 hours later), then every night at 2100. Never skip it for NPO, nausea or a low-normal glucose without a prescriber decision.', info: 'Without a long-acting depot, stopping the infusion lets ketones return within hours.', due: [T('Mon', '19:30'), T('Tue', '21:00'), T('Wed', '21:00')], dueDoses: ['22 units (2 hours before the infusion stops)', '22 units (bedtime)', '22 units (bedtime)'], monitor: [POC] });
med({ key: 'lispro_ac', name: 'insulin lispro (HUMALOG) pen U-100 - meal dose plus correction', dose: '6 units with each meal (about 60 g carbohydrate) PLUS correction from the premeal POC glucose: 151-200: +1 unit; 201-250: +2; 251-300: +3; over 300: +4 and call the prescriber', route: 'Subcutaneous', frequency: 'Three times daily before meals (first dose 1930 with dinner on Day 1); no correction at bedtime; HOLD the meal dose while NPO', kind: 'sched', start: T('Mon', '19:30'), end: T('Thu', '07:00'), provider: WHO.endo, orderedAt: T('Mon', '19:15'), drugClass: 'Rapid-acting (bolus) insulin', highAlert: true, dispense: 'Pharmacy: patient-specific pen',
  rationale: 'Home regimen 6 units with meals plus 1 unit per 50 mg/dL over 150, continued as a low-dose scale (about 1 unit per 10 g carbohydrate). The morning dose is held while he is NPO for the catheterization; the basal insulin is never held.', instructions: 'Give within 15 minutes of the meal tray. If he eats under half of the meal call the prescriber for a dose decision. Use the premeal POC for the correction and verify with a second nurse. No bedtime correction.', due: [T('Mon', '19:30'), T('Tue', '07:30'), T('Tue', '13:00'), T('Tue', '17:30'), T('Wed', '07:30'), T('Wed', '12:00'), T('Wed', '17:30')], dueDoses: ['6 units with dinner + correction per the premeal POC', 'NPO for the catheterization: HOLD the meal dose; the basal insulin is already on board', '6 units with lunch + correction per the premeal POC', '6 units with dinner + correction per the premeal POC', '6 units with breakfast + correction per the premeal POC', '6 units with lunch + correction per the premeal POC', '6 units with dinner + correction per the premeal POC'], monitor: [POC] });
plain('Nursing', 'DKA resolution confirmed on the 1850 specimen (BHB 0.4, venous pH 7.38, bicarbonate 22, gap 12, glucose 165). Give glargine at 1930 with lispro and dinner, and continue the IV insulin (reduced to 2 units/h at 1915) and the D5 0.45% NaCl + KCl 20 mEq/L carrier until 2130 (a full 2-hour overlap). Stop BOTH at 2130 only after the glargine dose is verified, he has eaten, and POC is checked. Disconnect the insulin tubing and clear the residual drug before saline-locking. Keep the left forearm IV as a saline lock; flush', T('Mon', '19:15'), { provider: WHO.endo, orderedAt: T('Mon', '19:15'), frequency: 'Once', end: T('Mon', '21:30'), instructions: 'Do not stop the infusion before the glargine has had its 2 hours. Extra POC at 2130 and 0300.' });
plain('Diet', 'Consistent-carbohydrate (about 60 g per meal), heart-healthy diet (low saturated fat, under 2,000 mg sodium) from the dinner tray at 1930', T('Mon', '19:30'), { provider: WHO.hospD, orderedAt: T('Mon', '19:15'), end: T('Tue', '00:00'), stoppedEarly: true });
med({ key: 'metoprolol_tart', name: 'metoprolol tartrate (LOPRESSOR) tablet', dose: '12.5 mg', route: 'Oral', frequency: 'Every 12 hours at 0800 and 2000 (first dose 2000 on Day 1)', kind: 'sched', start: T('Mon', '20:00'), end: T('Wed', '08:00'), stoppedEarly: false, provider: WHO.cards, orderedAt: T('Mon', '19:45'), drugClass: 'Beta-blocker', hold: 'Heart rate under 55 or systolic BP under 100 (hold and call)', rationale: 'NSTEMI: oral beta-blocker once there is no heart failure, low-output state or shock risk. Deferred this morning (volume depletion and tachycardia from DKA, which keeps him dependent on his sympathetic tone); started now that the acidosis and volume deficit have resolved. May blunt tachycardia and tremor of hypoglycemia (sweating is not blocked).', instructions: 'Check heart rate and blood pressure immediately before each dose. HOLD and call for heart rate under 55 or systolic BP under 100, new wheeze, new heart block or signs of heart failure. Give the Day 2 morning dose with a sip of water while NPO. Converted to metoprolol succinate on Day 3 (next order).', due: [T('Mon', '20:00'), T('Tue', '08:00'), T('Tue', '20:00')], dueDoses: ['12.5 mg (first dose; check HR and BP first)', '12.5 mg with a sip of water (NPO for the catheterization)', '12.5 mg'] });
// ---- Day 2
med({ key: 'ns_cath', name: '0.9% sodium chloride 1,000 mL bag, hydration around the catheterization', dose: '100 mL/h (1.25 mL/kg/h)', route: 'IV', frequency: 'Continuous 0700-1900 on Day 2 (about 4 hours before and 6-8 hours after the contrast)', kind: 'cont', start: T('Tue', '07:00'), end: T('Tue', '19:00'), provider: WHO.hospN, orderedAt: T('Mon', '20:30'), drugClass: 'Isotonic crystalloid', concentration: 'NS 1,000 mL bag', dispense: 'Central Pharmacy (IV room)', rationale: 'Contrast-associated kidney injury prevention after DKA volume depletion and a creatinine of 1.35 on arrival (0.95 at 1850): isotonic saline, with lungs and the LVEDP watched. Contrast volume kept small.', instructions: '100 mL/h by pump through the left forearm IV. Listen to the lungs every 4 hours; stop and call for crackles, new oxygen need or a rising weight. Ends at 1900 and the IV is saline-locked.', due: [T('Tue', '07:00')], dueDoses: ['Start 100 mL/h'], monitor: [CRMON] });
plain('Diet', 'NPO from midnight except medicines with small sips until the catheterization is done; POC glucose continues; basal insulin is given as ordered', T('Tue', '00:00'), { provider: WHO.hospN, orderedAt: T('Mon', '20:30'), end: T('Tue', '13:00'), stoppedEarly: true, instructions: 'Hold the 0730 mealtime lispro while NPO. Never hold the basal glargine in type 1 diabetes.' });
med({ key: 'aspirin_ec', name: 'aspirin enteric-coated tablet', dose: '81 mg', route: 'Oral', frequency: 'Once daily at 0800 starting Day 2', kind: 'sched', start: T('Tue', '08:00'), end: T('Thu', '07:00'), provider: WHO.cards, orderedAt: T('Mon', '09:35'), drugClass: 'Antiplatelet', rationale: 'Lifelong aspirin after the 324 mg load; with ticagrelor the maintenance aspirin dose must stay at 100 mg or less (81 mg).', instructions: 'Give with a sip of water. Bleeding precautions.', due: [T('Tue', '08:00'), T('Wed', '08:00')] });
plain('Cardiology', 'Cardiac catheterization (coronary angiography with possible PCI) via the right radial artery at 1100 on Day 2: consent, bilateral radial and ulnar assessment with the modified Allen test, mark radial and pedal pulses, NPO, hold the heparin infusion at 1030, transport at 1040. Right arm: no blood pressure cuff, venipuncture or IV', T('Tue', '11:00'), { provider: WHO.cards, orderedAt: T('Mon', '09:35'), frequency: 'Once', end: T('Tue', '12:15'), instructions: 'Baseline creatinine from the Day 2 0700 BMP. Metformin is not a home medicine. No iodinated contrast allergy.' });
plain('Nursing', 'Right antecubital IV (heparin line) removed at 1035 after the heparin is held: the right arm is the radial access side. Left forearm IV stays for hydration', T('Tue', '10:35'), { provider: WHO.hospN, orderedAt: T('Tue', '06:30'), frequency: 'Once', end: T('Tue', '10:45') });
med({ key: 'ticagrelor_load', name: 'ticagrelor (BRILINTA) tablet, loading dose', dose: '180 mg', route: 'Oral', frequency: 'Once, in the cath lab after the stent is placed', kind: 'sched', start: T('Tue', '12:15'), end: T('Tue', '12:20'), provider: WHO.ic, orderedAt: T('Tue', '12:10'), drugClass: 'P2Y12 platelet inhibitor', highAlert: true, by: RN.cath, rationale: 'Drug-eluting stent in the first obtuse marginal after an NSTEMI. The loading dose waited for the anatomy (multivessel disease would have meant a surgical opinion).', times: [T('Tue', '12:15')], doses: ['180 mg PO on the table (1215)'], status: 'Completed' });
med({ key: 'ticagrelor_90', name: 'ticagrelor (BRILINTA) tablet', dose: '90 mg', route: 'Oral', frequency: 'Every 12 hours, first dose 12 hours after the load (0000 on Day 3), then 1200 and 0000', kind: 'sched', start: T('Wed', '00:00'), end: T('Thu', '07:00'), provider: WHO.ic, orderedAt: T('Tue', '12:15'), drugClass: 'P2Y12 platelet inhibitor', highAlert: true, rationale: 'Dual antiplatelet therapy with aspirin 81 mg for at least 12 months. Maintenance starts 12 hours after the 180 mg load. NEVER miss or stop early without the cardiologist: stent thrombosis. Dyspnea can occur as a benign side effect; bleeding precautions (the radial hematoma at 1900 on Day 2 occurred on aspirin plus ticagrelor).', instructions: 'Give at 0000 and 1200 (12 hours apart). Pharmacy and cardiology will pick a home schedule with him before discharge. Report black stools, blood in urine, a nosebleed over 15 minutes or a severe headache.', due: [T('Wed', '00:00'), T('Wed', '12:00'), T('Thu', '00:00')], monitor: [mon('Hemoglobin', 'lab', 'Hemoglobin')] });
plain('Cardiology', 'Post-catheterization and PCI orders (drug-eluting stent to the first obtuse marginal, right radial access): heparin infusion stays OFF; right radial compression band: keep inflated 2 hours, then deflate 2-3 mL every 15-30 minutes starting at 1430 and remove at 1600 if there is no bleeding; right radial neurovascular checks (pulse, ulnar flow, capillary refill, color, temperature, sensation, bleeding and hematoma) every 15 minutes x4, every 30 minutes x4, hourly x4, then every 4 hours; no blood pressure cuff, venipuncture or lifting over 5 pounds with the right arm; 12-lead ECG on return to the unit (1300); BMP at 1845 and 0645 on Day 3 and 0645 on Day 4', T('Tue', '12:15'), { provider: WHO.ic, orderedAt: T('Tue', '12:10'), end: T('Wed', '07:00'), instructions: 'Keep the right wrist straight on a pillow. Call for bleeding, an expanding or pulsatile lump, a cool or pale hand, or numbness. Fluids encouraged for contrast clearance.' });
plain('Cardiology', 'ECG 12-lead on return to the unit; acquire 1300, interpretation released 1310', T('Tue', '13:00'), { provider: WHO.ic, orderedAt: T('Tue', '12:15'), frequency: 'Once', end: T('Tue', '13:10') });
plain('Diet', 'Consistent-carbohydrate (about 60 g per meal), heart-healthy (low saturated fat, under 2,000 mg sodium) diet; fluids encouraged; resume after the catheterization', T('Tue', '13:00'), { provider: WHO.ic, orderedAt: T('Tue', '12:15'), end: T('Thu', '07:00') });
plain('Nursing', 'Activity after the catheterization: in bed with the right wrist straight until the band is off, then chair and walking in the room; no lifting over 5 pounds or pushing up with the right arm for 1 week', T('Tue', '13:00'), { provider: WHO.ic, orderedAt: T('Tue', '12:15'), end: T('Thu', '07:00') });
plain('Consults', 'Clinical dietitian (carbohydrate counting for type 1 diabetes with a post-MI Mediterranean-style, low-sodium plan); cardiac rehabilitation (inpatient Phase I mobilization and outpatient Phase II referral); case management and social work (commercial driver license medical leave paperwork and medication affordability); tobacco treatment specialist', T('Tue', '14:00'), { provider: WHO.hospD, orderedAt: T('Tue', '14:00'), frequency: 'Once', end: T('Thu', '07:00'), instructions: 'Visits on Day 3: tobacco 1000, dietitian 1130, cardiac rehabilitation 1400, case management 1530.' });
med({ key: 'losartan', name: 'losartan (COZAAR) tablet', dose: '25 mg', route: 'Oral', frequency: 'First dose 1630 on Day 2, then once daily at 0800 from Day 3', kind: 'sched', start: T('Tue', '16:30'), end: T('Thu', '07:00'), provider: WHO.cards, orderedAt: T('Tue', '16:15'), drugClass: 'Angiotensin receptor blocker', hold: 'Systolic BP under 100, potassium above 5.0, or creatinine up 0.3 or more', rationale: 'Post-NSTEMI remodeling protection and kidney protection in type 1 diabetes. An ARB rather than an ACE inhibitor because lisinopril caused a persistent dry cough (intolerance, not allergy). Started after the contrast exposure with normal creatinine (0.92) and potassium (4.3) and no hypotension.', instructions: 'Check blood pressure before each dose; HOLD and call for systolic BP under 100, K above 5.0, or a creatinine rise of 0.3 or more after the contrast. The Day 3 0800 dose follows the 0700 BMP. BMP again within a week of discharge.', due: [T('Tue', '16:30'), T('Wed', '08:00')], monitor: [KMON, CRMON] });
plain('Nursing', 'Right radial hematoma (1.5 cm, 1900): direct firm manual pressure just proximal to the puncture for 15 minutes, mark the borders with a skin marker, reinforced pressure dressing and padded wrist splint until 2300, neurovascular checks every 15 minutes x4 then every 30 minutes x2 then hourly x4 then every 4 hours; no lifting, pushing up or reaching with the right arm; call the cardiology fellow for any expansion, pulsation, bruit, a cool hand or numbness. Do not stop aspirin or ticagrelor', T('Tue', '19:20'), { provider: WHO.fellow, orderedAt: T('Tue', '19:20'), end: T('Wed', '07:00'), instructions: 'Antiplatelet therapy continues unless the cardiologist decides otherwise (stent). Document the border measurements.' });
med({ key: 'atorvastatin_80', name: 'atorvastatin (LIPITOR) tablet', dose: '80 mg', route: 'Oral', frequency: 'Once daily at 2100 starting Day 2 (the ED dose at 0500 on Day 1 counted as the Day 1 dose)', kind: 'sched', start: T('Tue', '21:00'), end: T('Thu', '07:00'), provider: WHO.cards, orderedAt: T('Mon', '09:35'), drugClass: 'Statin (high intensity)', rationale: 'High-intensity statin after an NSTEMI (LDL 162, goal under 70 and lower). No interaction problem with ticagrelor at this dose. Raise the home 20 mg dose to 80 mg; he missed 3-4 doses a week.', due: [T('Tue', '21:00'), T('Wed', '21:00')] });
plain('Cardiology', 'Transthoracic echocardiogram on Day 3 at 1300 (left ventricular function and wall motion after the NSTEMI and stent)', T('Wed', '13:00'), { provider: WHO.cards, orderedAt: T('Tue', '16:15'), frequency: 'Once', end: T('Wed', '14:40') });
// ---- Day 3
med({ key: 'metoprolol_succ', name: 'metoprolol succinate extended-release (TOPROL-XL) tablet', dose: '50 mg', route: 'Oral', frequency: 'Once daily at 0800 from Day 3 (replaces metoprolol tartrate)', kind: 'sched', start: T('Wed', '08:00'), end: T('Thu', '07:00'), provider: WHO.cards, orderedAt: T('Tue', '16:15'), drugClass: 'Beta-blocker (extended release)', hold: 'Heart rate under 55 or systolic BP under 100 (hold and call)', rationale: 'Once-daily simplification after 24-hour renal stability. NOTE: 50 mg is double the 25 mg per day he has had (an intended step up for post-NSTEMI therapy while his resting heart rate and blood pressure leave room); it needs the same hold parameters and a check of his heart rate during the first day.', instructions: 'Check heart rate and blood pressure before the dose; do not crush. HOLD and call for heart rate under 55 or systolic BP under 100. Warn him that it can mask the racing heart of a low glucose; sweating is not masked.', due: [T('Wed', '08:00')] });
med({ key: 'nicotine_patch', name: 'nicotine transdermal patch', dose: '21 mg/24 hours', route: 'Transdermal', frequency: 'Once daily; first patch Day 3 at 1000, then change every morning at 0800 (remove the old patch)', kind: 'sched', start: T('Wed', '10:00'), end: T('Thu', '07:00'), provider: WHO.hospD, orderedAt: T('Wed', '09:00'), drugClass: 'Smoking cessation (nicotine replacement)', rationale: 'Intense withdrawal after 52 hours without a cigarette (1 pack/day, first cigarette within 30 minutes of waking). Nicotine replacement is acceptable after a stable PCI and cardiology agrees; smoking is a much larger risk for stent thrombosis.', instructions: 'Apply to clean, dry, hairless skin of the upper chest or left upper arm (not over the right radial site); rotate sites; remove the old patch first. Taper plan at discharge: 21 mg for 4 weeks, 14 mg for 2 weeks, then 7 mg for 2 weeks (8 weeks).', due: [T('Wed', '10:00')], dueDoses: ['21 mg patch to the left upper chest (first patch)'] });
med({ key: 'nicotine_lozenge', name: 'nicotine polacrilex lozenge, as needed', dose: '2 mg', route: 'Oral', frequency: 'Every 2 hours as needed for strong cravings with the patch; one at a time, maximum 20 per day', kind: 'prn', prn: true, start: T('Wed', '10:00'), end: T('Thu', '07:00'), provider: WHO.hospD, orderedAt: T('Wed', '09:00'), drugClass: 'Smoking cessation (nicotine replacement)', rationale: 'Breakthrough cravings (stress, meals, breaks).', instructions: 'Let it dissolve slowly between cheek and gum for 20-30 minutes; do not chew or swallow; no food or acidic drinks for 15 minutes before.' });
plain('Nursing', 'Smoking cessation: no tobacco on the unit; tobacco treatment specialist visit at 1000; telephone quit-line coaching referral; 8-week nicotine taper plan with the discharge prescriptions', T('Wed', '09:00'), { provider: WHO.hospD, orderedAt: T('Wed', '09:00'), end: T('Thu', '07:00') });
plain('Discharge', 'Home discharge planned for about 0900 on Day 4 after: the 0700 labs, morning medicines (aspirin, ticagrelor timing, metoprolol succinate, losartan, nicotine patch change), breakfast insulin, radial site check and structured teach-back with his wife. Home regimen: glargine 22 units at bedtime; lispro 6 units with meals plus correction; aspirin 81 mg daily; ticagrelor 90 mg every 12 hours for 12 months (no missed doses); atorvastatin 80 mg at bedtime; metoprolol succinate 50 mg daily; losartan 25 mg daily; nitroglycerin 0.4 mg SL as needed; nicotine patch 21 mg plus lozenge 2 mg as needed with the 8-week taper; blood ketone meter and strips. STOP calcium carbonate for "indigestion". Follow-up: cardiology and endocrinology in 1 week (BMP for losartan and contrast), cardiac rehabilitation Phase II in 2 weeks', T('Thu', '07:00'), { provider: WHO.hospD, orderedAt: T('Thu', '06:50'), frequency: 'Once', end: T('Thu', '07:00'), instructions: 'Not yet carried out. If glucose is unstable, a heart rate or blood pressure parameter fails, the right wrist worsens, chest discomfort recurs, or teach-back is incomplete, reassess instead of discharging.' });
// hypoglycemia orders (from the insulin start)
med({ key: 'glucose_po_hypo', name: 'glucose 15 g rapid carbohydrate by mouth (juice 120 mL) - hypoglycemia protocol, nurse-driven', dose: '15 g (120 mL juice)', route: 'Oral', frequency: 'As needed for glucose under 70 when awake and able to swallow; recheck in 15 minutes and repeat until 70 or higher', kind: 'prn', prn: true, start: T('Mon', '02:15'), provider: WHO.ed, orderedAt: T('Mon', '02:10'), end: T('Thu', '07:00'), drugClass: 'Carbohydrate', rationale: 'Insulin therapy; a beta-blocker (from Day 1 2000) can blunt some warning symptoms.', instructions: 'Rule of 15: 15 g fast carbohydrate, recheck in 15 minutes and repeat until 70 or higher; then a snack if the next meal is more than 1 hour away. Count the volume on the I&O. Hold rapid-acting insulin and notify the prescriber.' });
med({ key: 'd10_hypo', name: 'dextrose 10% injection (hypoglycemia protocol)', dose: '150 mL (15 g) over 15 minutes', route: 'IV', frequency: 'As needed for glucose under 70 when unable to swallow safely and an IV is in place; recheck every 15 minutes; notify the provider', kind: 'prn', prn: true, start: T('Mon', '02:15'), provider: WHO.ed, orderedAt: T('Mon', '02:10'), end: T('Thu', '07:00'), drugClass: 'Carbohydrate', rationale: 'Insulin therapy; unsafe swallow.', instructions: 'Give through a running peripheral line, never into the insulin line. Count the volume on the I&O.' });
med({ key: 'glucagon_hypo', name: 'glucagon injection (hypoglycemia protocol)', dose: '1 mg', route: 'Intramuscular', frequency: 'As needed once for glucose under 70 when unable to swallow and there is no IV access; summon urgent help', kind: 'prn', prn: true, start: T('Mon', '02:15'), provider: WHO.ed, orderedAt: T('Mon', '02:10'), end: T('Thu', '07:00'), drugClass: 'Antihypoglycemic', rationale: 'Insulin therapy; no IV access.', instructions: 'Turn him on his side (vomiting is common after glucagon). Call for urgent help while IV access is obtained.' });
